// #6a8560fb — TC-CHAT-01, TC-CHAT-02 (chat with the other test account only; sends nothing)
import assert from 'node:assert/strict';
import { startDriver, byText, tapXY, keyboardShown, search, PARTNER, IS_IOS } from '../lib/session.js';

describe('Chat keyboard & bottom nav #6a8560fb @ios @android @prod-safe', function () {
  let d; let win;
  before(async () => { d = await startDriver(); win = await d.getWindowSize(); });
  after(async () => { if (d) await d.deleteSession(); });

  async function openChatFromWorkerSearch() {
    await search(d, 'עובדים', PARTNER.name.split(' ')[0]);
    const name = await byText(d, PARTNER.name, true);
    await name.waitForDisplayed({ timeout: 20000 });
    const chatBtn = await byText(d, 'צ׳אט');
    await chatBtn.click();
    // in chat: partner header visible, bottom nav hidden
    await (await byText(d, PARTNER.name.split(' ')[0], true)).waitForDisplayed({ timeout: 15000 });
  }

  const inputPoint = () => ({ x: win.width / 2, y: win.height - (IS_IOS ? 40 : 75) });
  const emptyPoint = () => ({ x: win.width * 0.3, y: win.height * 0.38 });

  it('TC-CHAT-02: no bottom navigation inside chat opened from search, nav back after exit', async () => {
    await openChatFromWorkerSearch();
    assert.equal(await (await byText(d, 'חיפוש')).isDisplayed().catch(() => false), false, 'bottom nav must be hidden in chat');
    if (IS_IOS) await tapXY(d, win.width - 28, 94); else await d.back();
    await (await byText(d, 'חיפוש')).waitForDisplayed({ timeout: 10000 });
  });

  it('TC-CHAT-01: one tap on empty area closes keyboard, 10 times in a row', async () => {
    await openChatFromWorkerSearch();
    for (let i = 1; i <= 10; i++) {
      const p = inputPoint(); await tapXY(d, p.x, p.y);
      await d.waitUntil(() => keyboardShown(d), { timeout: 5000, timeoutMsg: `run ${i}: keyboard did not open` });
      const e = emptyPoint(); await tapXY(d, e.x, e.y);
      await d.waitUntil(async () => !(await keyboardShown(d)), { timeout: 3000, timeoutMsg: `run ${i}: keyboard still open after one tap` });
    }
  });
});
